-- Artenkatalog erweitert:
--  * translations: Steckbrief-Texte in weiteren Sprachen ({"en": {"distribution": …}}); die
--    deutschen Spalten bleiben die Quelle, fehlende Übersetzungen fallen auf sie zurück.
--  * eu_invasive: Arten der Unionsliste invasiver gebietsfremder Arten (Verordnung (EU)
--    Nr. 1143/2014) – Haltung verboten; die App warnt im Steckbrief und bei Kolonien.
--    Ameisen seit der Durchführungsverordnung (EU) 2022/1203 (gilt seit 2. August 2022).
--  * user_settings.flight_watch: Arten, deren Schwarmflugzeit die App ankündigen soll.
ALTER TABLE species
    ADD COLUMN translations jsonb   NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(translations) = 'object'),
    ADD COLUMN eu_invasive  boolean NOT NULL DEFAULT false;

ALTER TABLE user_settings
    ADD COLUMN flight_watch jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(flight_watch) = 'array');

