UPDATE species SET translations = jsonb_build_object('en', '{"german_name": "Pavement ant", "distribution": "Europe, temperate Asia; introduced to North America", "habitat": "Open, sunny areas, roadsides, lawns", "worker_size": "2.5–4 mm", "coloration": "Dark brown to black", "hibernation_period": "October – March", "colony_size": "up to several 10,000 workers", "queen_lifespan": "over 10 years", "development": "approx. 6–8 weeks", "nuptial_flight": "June – July", "diet_protein": "Insects, also seeds", "diet_carbohydrate": "Honey water, sugar water", "nesting": "Soil nests under stones and in paving cracks", "formicarium": "Ytong, plaster, acrylic", "substrate": "Sand-loam mix", "notes": "Actually a species complex, hardly distinguishable in the field. Active, can sting, but weakly."}'::jsonb)
    WHERE owner_id IS NULL AND scientific_name = 'Tetramorium caespitum';
UPDATE species SET translations = jsonb_build_object('en', '{"german_name": "Electric ant (little fire ant)", "distribution": "Central and South America; spread to many tropical regions", "legal_note": "EU: invasive alien species of Union concern (Implementing Regulation (EU) 2022/1203, in force since 2 August 2022). Keeping, breeding, buying, selling, transporting and releasing are prohibited in the EU (Regulation (EU) No 1143/2014, Art. 7).", "notes": "Do not keep. Report suspected finds in the wild to the responsible nature conservation authorities."}'::jsonb)
    WHERE owner_id IS NULL AND scientific_name = 'Wasmannia auropunctata';
